    LANGUAGE_WRAPPER = 'Fix a base {base}. Consider all {n_digits}-digit base-{base} integers with digit sequence d_1, d_2, ..., d_{n_digits} and with d_1 ≠ 0. Call such an integer tri-balanced if the sum of its first {k_block} digits equals the sum of its last {k_block} digits, if the alternating sum d_1 − d_2 + d_3 − d_4 + ⋯ with + at odd positions and − at even positions is congruent to {residue_mod_m} modulo {mod_m}, and if the sum of the digits whose positions are prime numbers is congruent to {residue_mod_p} modulo {mod_p}. How many tri-balanced integers are there?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

