import math

def primes_upto(n):
    ps = []
    for i in range(2, n+1):
        is_p = True
        r = int(math.isqrt(i))
        for d in range(2, r+1):
            if i % d == 0:
                is_p = False
                break
        if is_p:
            ps.append(i)
    return ps

def count_tri(base, n, k, m, r, p, q):
    prime_set = set(primes_upto(n))
    if not prime_set:
        return 0
    dp = {(0, 0, 0): 1}
    for i in range(1, n+1):
        next_dp = {}
        sign = 1 if (i % 2 == 1) else -1
        digits = range(1, base) if i == 1 else range(0, base)
        for (diff, alt, prm), cnt in dp.items():
            for d in digits:
                ndiff = diff
                if i <= k:
                    ndiff += d
                elif i > n - k:
                    ndiff -= d
                nalt = (alt + sign * d) % m
                nprm = prm
                if i in prime_set:
                    nprm = (prm + d) % p
                key = (ndiff, nalt, nprm)
                next_dp[key] = next_dp.get(key, 0) + cnt
        dp = next_dp
    return dp.get((0, r % m, q % p), 0)

# Try multiple times to get a nontrivial instance
for _ in range(120):
    base = rng.randint(5, 12)
    n = rng.randint(6, 12)
    k = rng.randint(2, n // 2)
    m = rng.randint(3, 9)
    p = rng.randint(3, 9)
    r = rng.randint(0, m - 1)
    q = rng.randint(0, p - 1)
    ans = count_tri(base, n, k, m, r, p, q)
    total = (base - 1) * (base ** (n - 1))
